// Auditory calibration tone generated by FFmpeg (1.05s, mono MP3 16kbps).
// Same-origin, no upstream service required. Supports media byte ranges.
const TONE = '';
let bytesCache = null;
function bytes() {
  if (bytesCache) return bytesCache;
  const decoded = atob(TONE);
  const data = new Uint8Array(decoded.length);
  for (let i = 0; i < decoded.length; i++) data[i] = decoded.charCodeAt(i);
  bytesCache = data;
  return data;
}
export async function onRequest(context) {
  const request = context.request;
  if (request.method !== 'GET' && request.method !== 'HEAD')
    return new Response('Method Not Allowed', {status:405});
  const source = bytes();
  const total = source.length;
  const headers = new Headers({
    'Content-Type':'audio/mpeg',
    'Accept-Ranges':'bytes',
    'Cache-Control':'public,max-age=3600',
    'X-Content-Type-Options':'nosniff',
    'Access-Control-Allow-Origin':new URL(request.url).origin
  });
  let start=0, end=total-1, status=200;
  const range=request.headers.get('Range');
  if (range) {
    const match=/^bytes=(\d*)-(\d*)$/.exec(range);
    if(!match || (!match[1] && !match[2])) {
      headers.set('Content-Range','bytes */'+total);
      return new Response(null,{status:416,headers});
    }
    if (!match[1]) {
      const suffix=Number(match[2]);
      start=Math.max(0,total-suffix);
    } else {
      start=Number(match[1]);
      end=match[2]?Math.min(total-1,Number(match[2])):total-1;
    }
    if (start>=total||end<start) {
      headers.set('Content-Range','bytes */'+total);
      return new Response(null,{status:416,headers});
    }
    status=206;
    headers.set('Content-Range','bytes '+start+'-'+end+'/'+total);
  }
  headers.set('Content-Length',String(end-start+1));
  return new Response(request.method==='HEAD'?null:source.slice(start,end+1),
    {status,headers});
}
